package pl.fhframework.fhdp.example.camunda;

import pl.fhframework.annotations.Action;
import pl.fhframework.core.uc.IInitialUseCase;
import pl.fhframework.core.uc.UseCase;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Base64;

@UseCase
public class ExampleCamundaUC implements IInitialUseCase {

    private ExampleCamundaForm.Model model;

    String bpmn = new String(Base64.getDecoder().decode(""));

    @Override
    public void start() {
        ExampleCamundaForm.Model model = new ExampleCamundaForm.Model();
        this.model = model;
        this.model.getBpmns().add(bpmn);
        this.model.setProcessDefinitionBpmn(bpmn);

        showForm(ExampleCamundaForm.class, this.model);

      this.getActiveForm().refreshView();
    }

    @Action(validate = false)
    public void fileUploadMenu() throws IOException {
        String bpmn = new String(Files.readAllBytes(Paths.get(model.getFileScan().getURI())), StandardCharsets.UTF_8);
        model.getBpmns().add(bpmn);
        model.setProcessDefinitionBpmn(bpmn);
    }

    @Action
    public void close() {
        exit();
    }

    @Action
    public void refresh() {
        this.getActiveForm().refreshView();
    }
}
